mapper.select:
SELECT id, user_id, problem_id, language, status, time_ms, created_at
FROM submission
WHERE id = #{id}

SELECT COUNT(*)
FROM submission
WHERE user_id = #{userId}

SELECT id, user_id, problem_id, language, status, time_ms, created_at
FROM submission
WHERE problem_id = #{problemId}
ORDER BY created_at DESC, id DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE submission
SET status = #{status}, time_ms = #{timeMs}
WHERE id = #{id}
